ts\');\\r\\n\\r\\n    let currentIndex = 0;\\r\\n    let autoPlay = setInterval(nextSlide, 5000);\\r\\n\\r\\n    slides.forEach((_, i) => {\\r\\n      const dot = document.createElement(\'div\');\\r\\n      dot.classList.add(\'carousel-dot\');\\r\\n\\r\\n      if (i === 0) {\\r\\n        dot.classList.add(\'active\');\\r\\n      }\\r\\n\\r\\n      dot.addEventListener(\'click\', () => {\\r\\n        goToSlide(i);\\r\\n        resetAutoPlay();\\r\\n      });\\r\\n\\r\\n      dotsNav.appendChild(dot);\\r\\n    });\\r\\n\\r\\n    const dots = Array.from(dotsNav.children);\\r\\n\\r\\n    function updateSlidePosition() {\\r\\n      track.style.transform = `translateX(-${currentIndex * 100}%)`;\\r\\n      dots.forEach(dot => dot.classList.remove(\'active\'));\\r\\n      dots[currentIndex].classList.add(\'active\');\\r\\n    }\\r\\n\\r\\n    function goToSlide(index) {\\r\\n      currentIndex = index;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function nextSlide() {\\r\\n      currentIndex = (currentIndex + 1) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function prevSlide() {\\r\\n      currentIndex = (currentIndex - 1 + slides.length) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function resetAutoPlay() {\\r\\n      clearInterval(autoPlay);\\r\\n      autoPlay = setInterval(nextSlide, 5000);\\r\\n    }\\r\\n\\r\\n    nextButton.addEventListener(\'click\', () => {\\r\\n      nextSlide();\\r\\n      resetAutoPlay();\\r\\n    });\\r\\n\\r\\n    prevButton.addEventListener(\'click\', () => {\\r\\n      prevSlide();\\r\\n      resetAutoPlay();\\r\\n    });\\r\\n  <\\/script>\\r\\n\\r\\n<\\/body>\\r\\n<\\/html>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"653a035\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"background_background\":\"gradient\",\"background_color_b\":\"\",\"__globals__\":{\"background_color\":\"globals\\/colors?id=41c3483\"},