'[data-tecnicos-search]\');\n      const feedback = app.querySelector(\'[data-tecnicos-feedback]\');\n      const empty = app.querySelector(\'[data-tecnicos-empty]\');\n      const rows = Array.from(app.querySelectorAll(\'.fisica-docentes-row\'));\n\n      const normalize = (value) => value\n        .normalize(\'NFD\')\n        .replace(/[\\u0300-\\u036f]/g, \'\')\n        .toLowerCase();\n\n      const filterRows = () => {\n        const term = normalize((search?.value || \'\').trim());\n        let visible = 0;\n\n        rows.forEach((row) => {\n          const match = term === \'\' || normalize(row.dataset.search || \'\').includes(term);\n          row.hidden = !match;\n          if (match) {\n            visible += 1;\n          }\n        });\n\n        if (empty) {\n          empty.hidden = visible !== 0;\n        }\n\n        if (feedback) {\n          feedback.textContent = term === \'\'\n            ? \'Consulte os 20 servidores técnicos. Atualização: 29/04/2026.\'\n            : visible === 1 ? \'1 servidor encontrado.\' : visible + \' servidores encontrados.\';\n        }\n      };\n\n      search?.addEventListener(\'input\', filterRows);\n      filterRows();\n    })();\n  </script>\n</section>','Técnicos','','publish','closed','closed','','tecnicos','','','2026-05-06 14:56:24','2026-05-06 17:56:24','',0,'http://localhost/fisica/?page_id=509',0,'page','',0),(510,1,'2025-09-26 14:42:55','2025-09-26 17:42:55','','Técnicos','','inherit','closed','closed','','509-revision-v1','','','2025-09-26 14:42:55','2025-09-26 17:42:55','',509,'http://localhost/fisica/?p=510',0,'revision','',0),(511,1,'2025-09-26 14:44:15','2025-09-26 17:44:15',' ','','','publish','closed','closed','','511','','','2026-05-06 15:47:36','2026-05-06 18:47:36','',0,'http://localhost/fisica/?p=511',27,'nav_menu_item','',0),(512,1,'2025-09-26 14:47:16','2025-09-26 17:47:16','<a href=\"http://localhost/fisica/\">\n							<img width=\"800\" height=\"267\" src=\"http://localhost/fisica/wp-conten